#include "simp/CodeGenerator.hpp"

#include <algorithm>
#include <stdexcept>

namespace simp {

const MethodDeclaration* CodeGenerator::findMethod(const ClassDeclaration& owner,
                                                    const std::string& name) const {
    for (const auto& method : owner.methods) {
        if (method.name == name && !method.constructor) return &method;
    }
    if (!owner.baseClassName.empty()) {
        const auto base = classes_.find(owner.baseClassName);
        if (base != classes_.end()) return findMethod(*base->second, name);
    }
    return nullptr;
}

std::vector<const MethodDeclaration*> CodeGenerator::methodSlots(
    const ClassDeclaration& owner) const {
    std::vector<const ClassDeclaration*> hierarchy;
    auto* current = &owner;
    while (current != nullptr) {
        hierarchy.push_back(current);
        if (current->baseClassName.empty()) break;
        const auto base = classes_.find(current->baseClassName);
        current = base == classes_.end() ? nullptr : base->second;
    }
    std::reverse(hierarchy.begin(), hierarchy.end());

    std::vector<const MethodDeclaration*> slots;
    for (const auto* declaration : hierarchy) {
        for (const auto& method : declaration->methods) {
            if (method.constructor) continue;
            const auto inherited = std::find_if(
                slots.begin(), slots.end(), [&method](const MethodDeclaration* candidate) {
                    return candidate->name == method.name;
                });
            if (inherited == slots.end()) {
                slots.push_back(&method);
            } else {
                *inherited = &method;
            }
        }
    }
    return slots;
}

std::size_t CodeGenerator::methodSlot(const ClassDeclaration& owner,
                                      const std::string& name) const {
    const auto slots = methodSlots(owner);
    for (std::size_t index = 0; index < slots.size(); ++index) {
        if (slots[index]->name == name) return index;
    }
    throw std::logic_error("resolved method has no dispatch slot");
}

std::string CodeGenerator::declaringClass(const MethodDeclaration& method) const {
    for (const auto& entry : classes_) {
        for (const auto& candidate : entry.second->methods) {
            if (&candidate == &method) return entry.first;
        }
    }
    return {};
}

} // namespace simp
